class Solution:
    def numberOfGoodSubarraySplits(self, nums: List[int]) -> int:
        MOD = 10 ** 9 + 7
        pos = [i for i, x in enumerate(nums) if x]
        if not pos:
            return 0
        ans = 1
        for a, b in zip(pos, pos[1:]):
            ans = ans * (b - a) % MOD
        return ans

