class Solution {
public:
    int numberOfGoodSubarraySplits(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        vector<int> pos;
        for (int i = 0; i < (int)nums.size(); i++)
            if (nums[i]) pos.push_back(i);
        if (pos.empty()) return 0;
        long long ans = 1;
        for (size_t i = 1; i < pos.size(); i++)
            ans = ans * (pos[i] - pos[i - 1]) % MOD;
        return ans;
    }
};

