class Solution:
    def numberOfGoodSubarraySplits(self, nums: List[int]) -> int:
        MOD = 10 ** 9 + 7
        ans, prev, seen = 1, -1, False
        for i, x in enumerate(nums):
            if x:
                if seen:
                    ans = ans * (i - prev) % MOD
                prev, seen = i, True
        return ans if seen else 0

