        const long long MOD = 1e9 + 7;
        long long ans = 1;
        int prev = -1;
        bool seen = false;
        for (int i = 0; i < (int)nums.size(); i++)
            if (nums[i]) {
                if (seen) ans = ans * (i - prev) % MOD;
                prev = i; seen = true;
            }
        return seen ? ans : 0;
    }
};

